// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new W_WALLET(address(lg));
    }

    function testFuzz_property(uint256 amount, address actor1, address actor2) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1 ether);
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != actor2);
        vm.assume(actor1 != address(c) && actor2 != address(c));

        vm.deal(actor1, 2 * amount + 1);
        vm.deal(actor2, amount + 1);

        // actor1 deposits `amount`
        vm.prank(actor1);
        c.Put{value: amount}(0);

        // actor2 deposits a different amount `amount` (independently fuzzed scenario value)
        vm.prank(actor2);
        c.Put{value: amount}(0);

        // actor1 repeats the exact same deposit `amount`
        vm.prank(actor1);
        c.Put{value: amount}(0);

        (, , uint256 valFirst, ) = lg.History(0);
        (, , uint256 valRepeat, ) = lg.History(2);

        // General rule: the logged Val of a Put is determined solely by the value sent
        // in that call, so repeating the same deposit logs the same Val even after
        // intervening deposits by other actors. The mutant logs the sender's running
        // balance, so the repeat logs amount + (earlier balance) != amount.
        assertTrue(valFirst == valRepeat, "repeated equal deposit must log equal Val");
    }
}
